#ifndef STDLIB_MATH_BASE_SPECIAL_GAMMAINCINV_H
#define STDLIB_MATH_BASE_SPECIAL_GAMMAINCINV_H

// MODULES //

#include <stdbool.h>

// FUNCTIONS //

/**
* Inverts the lower incomplete gamma function.
*
* @param p - probability value
* @param a - scale parameter
* @param upper - boolean indicating if the function should invert the upper tail
* @return function value
*
* @example
* double y = stdlib_base_special_gammaincinv( 0.5, 1.0, false );
* // returns ~0.693
*/
double stdlib_base_special_gammaincinv( const double p, const double a, const bool upper );

#endif // !STDLIB_MATH_BASE_SPECIAL_GAMMAINCINV_H
